Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define LL long long
using namespace std;

inline int getInt(){
    int v=0,f=1;
    char c=getchar();
    while (c<'0' || c>'9'){
        if (c=='-') f=-1;
        c=getchar();
    }
    while (c>='0' && c<='9'){
        v=v*10+c-'0';
        c=getchar();
    }
    return v*f;
}

const int MAXN=10;
const LL MOD=1e9+7;

LL fastExponent(LL base, LL exp){
    LL res=1;
    while (exp){
        if (exp & 1) res=res*base%MOD;
        base=base*base%MOD;
        exp>>=1;
    }
    return res;
}

LL modInverse(LL x){
    return fastExponent(x, MOD-2);
}

int p[MAXN][MAXN], n;
int id[64], count_id, X_array[1048576], Y_array[1048576];

void updateAdd(int &x, int y){
    x+=y;
    if (x>=MOD) x-=MOD;
}

void updateSub(int &x, int y){
    x-=y;
    if (x<0) x+=MOD;
}

void fwTransform(int *arr, int mode){
    int N=1048576;
    for (int len=2; len<=N; len<<=1){
        for (int start=0; start<N; start+=len){
            for (int k=start; k<start+(len>>1); ++k){
                if (mode==1) updateAdd(arr[k], arr[k+(len>>1)]);
                else updateSub(arr[k], arr[k+(len>>1)]);
            }
        }
    }
}

int main(){
    int n= getInt();
    for (int i=0; i<n; i++){
        for (int j=0; j<n; j++){
            p[i][j]=1LL*getInt()*modInverse(100)%MOD;
        }
    }
    if (n<6){
        for (int i=n; i<6; i++) p[i][i]=1;
        n=6;
    }
    int A=(1<<6)-1;
    for (int i=0; i<64; i++){
        if (__builtin_popcount(i)==3) id[i]=count_id++;
    }
    for (int mask=0; mask<(1<<18); mask++){
        int msk1=mask&A, msk2=(mask>>6)&A, msk3=(mask>>12)&A;
        int combined_mask=0;
        LL probability=1;
        for (int j=0; j<6; j++){
            if (msk1>>j&1) probability=probability*p[0][j]%MOD;
            else probability=probability*(MOD+1-p[0][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk2>>j&1) probability=probability*p[1][j]%MOD;
            else probability=probability*(MOD+1-p[1][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk3>>j&1) probability=probability*p[2][j]%MOD;
            else probability=probability*(MOD+1-p[2][j])%MOD;
        }
        if (probability==0) continue;
        for (int a=0; a<6; a++){
            if (msk1>>a&1){
                for (int b=0; b<6; b++){
                    if (a==b) continue;
                    if (msk2>>b&1){
                        for (int c=0; c<6; c++){
                            if (a==c || b==c) continue;
                            if (msk3>>c&1){
                                int nmsk=(1<<a)|(1<<b)|(1<<c);
                                combined_mask|=1<<id[nmsk];
                            }
                        }
                    }
                }
            }
        }
        updateAdd(Y_array[combined_mask], int(probability));
    }

    for (int mask=0; mask<(1<<18); mask++){
        int msk1=mask&A, msk2=(mask>>6)&A, msk3=(mask>>12)&A;
        int combined_mask=0;
        LL probability=1;
        for (int j=0; j<6; j++){
            if (msk1>>j&1) probability=probability*p[3][j]%MOD;
            else probability=probability*(MOD+1-p[3][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk2>>j&1) probability=probability*p[4][j]%MOD;
            else probability=probability*(MOD+1-p[4][j])%MOD;
        }
        for (int j=0; j<6; j++){
            if (msk3>>j&1) probability=probability*p[5][j]%MOD;
            else probability=probability*(MOD+1-p[5][j])%MOD;
        }
        if (probability==0) continue;
        for (int a=0; a<6; a++){
            if (msk1>>a&1){
                for (int b=0; b<6; b++){
                    if (a==b) continue;
                    if (msk2>>b&1){
                        for (int c=0; c<6; c++){
                            if (a==c || b==c) continue;
                            if (msk3>>c&1){
                                int nmsk=(1<<a)|(1<<b)|(1<<c);
                                nmsk^=A;
                                updateAdd(X_array[nmsk], int(probability));
                            }
                        }
                    }
                }
            }
        }
    }

    fwTransform(X_array, 1);
    fwTransform(Y_array, 1);
    for (int i=0; i<1048576; i++){
        X_array[i]=1LL*X_array[i]*Y_array[i]%MOD;
    }
    fwTransform(X_array, -1);
    int answer=0;
    for (int i=1; i<1048576; i++) updateAdd(answer, X_array[i]);
    printf("%d\n", answer);
    return 0;
}
